def schema_drift(expected, actual):
    drift = set()

    def add_path(path):
        drift.add(path)

    def collect_leaf_paths(node, prefix):
        if isinstance(node, dict):
            for key, value in node.items():
                child_prefix = f"{prefix}.{key}" if prefix else key
                collect_leaf_paths(value, child_prefix)
        else:
            add_path(prefix)

    def compare(exp, act, prefix):
        keys = set(exp.keys()) | set(act.keys())
        for key in keys:
            path = f"{prefix}.{key}" if prefix else key
            in_exp = key in exp
            in_act = key in act

            if not in_exp:
                collect_leaf_paths(act[key], path)
            elif not in_act:
                collect_leaf_paths(exp[key], path)
            else:
                exp_val = exp[key]
                act_val = act[key]
                if isinstance(exp_val, dict) and isinstance(act_val, dict):
                    compare(exp_val, act_val, path)
                elif isinstance(exp_val, str) and isinstance(act_val, str):
                    if exp_val != act_val:
                        add_path(path)
                else:
                    add_path(path)

    compare(expected, actual, "")
    return sorted(drift)
