def bounded_batches(items, max_rows):
    if max_rows <= 0:
        raise ValueError("max_rows must be > 0")

    batches = []
    current_batch = []
    current_rows = 0

    for item in items:
        _, row_count = item

        if row_count > max_rows:
            if current_batch:
                batches.append(current_batch)
                current_batch = []
                current_rows = 0
            batches.append([item])
            continue

        if current_rows + row_count <= max_rows:
            current_batch.append(item)
            current_rows += row_count
        else:
            if current_batch:
                batches.append(current_batch)
            current_batch = [item]
            current_rows = row_count

    if current_batch:
        batches.append(current_batch)

    return batches

